const assert=require('node:assert/strict');const {chromium}=require('playwright');
(async()=>{const browser=await chromium.launch({headless:true,...(process.env.DSG_BROWSER_CHANNEL?{channel:process.env.DSG_BROWSER_CHANNEL}:{})});try{
 const base=process.env.DSG_TEST_BASE_URL||'http://127.0.0.1:8766/digital-stargate-manual/';const page=await browser.newPage({viewport:{width:1157,height:900}});await page.clock.install();const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.route('**/*',r=>new URL(r.request().url()).origin===new URL(base).origin?r.continue():r.abort());await page.goto(base+'analytics/dashboard/');const host=page.locator('[data-executive-dashboard]');await host.waitFor();
 assert.equal(await host.locator('.dsg-kpi-card').count(),21);assert.equal(await host.locator('#executive-sessions tbody tr').count(),12);
 const matches=await host.locator('#executive-sessions tbody tr').evaluateAll(rows=>rows.filter(r=>r.textContent.includes('QUATTRO')).length);await host.locator('[data-executive-search]').fill('QUATTRO');assert.equal(await host.locator('#executive-sessions tbody tr:visible').count(),matches);await host.locator('[data-executive-search]').fill('');
 for(const width of [1440,1157,768,390]){await page.setViewportSize({width,height:900});for(const theme of ['dark','light']){await page.evaluate(t=>window.DSGThemeService.setTheme(t),theme);assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));}}
 if(process.env.DSG_EXEC_SCREENSHOT){await page.setViewportSize({width:1157,height:900});await page.evaluate(()=>{window.DSGThemeService.setTheme('dark');scrollTo(0,0)});await page.screenshot({path:process.env.DSG_EXEC_SCREENSHOT,fullPage:true});}
 const html=await(await page.request.get(base+'analytics/dashboard/')).text();await page.route('**/analytics/dashboard/',r=>r.fulfill({status:200,contentType:'text/html',body:html.replace(/data-snapshot="[^"]+"/,'data-snapshot="next"').replace('Dal cielo al dato.','Nuovo snapshot')}));await page.clock.fastForward(300001);await page.getByRole('heading',{name:'Nuovo snapshot',exact:true}).waitFor();
 await page.route('**/analytics/dashboard/',r=>r.fulfill({status:503,body:'unavailable'}));await page.clock.fastForward(300001);await page.getByText('Aggiornamento non verificabile:',{exact:false}).waitFor();assert.deepEqual(errors,[]);console.log('PASS executive dashboard: preserved KPI/table counts, search, mobile/themes, new snapshot and failure notice');
}finally{await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1});
